import {STOPS,COMMON,fare,validTicket} from './core.js';
import {newRun,amount,committed,toggleStop,beginCounts,setCount,nextCount,editCount,method,confirmCash,requestUpi,resolveUpi,preparePrint,paidUnprinted,allPrinted,restoreRun,editDestination,cancelEdit,addJourney,cashChange} from './wizard-core.js';
import {encodeTicket,qrSVG} from './delivery.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],money=n=>'₹'+n;
const uid=prefix=>prefix+'-'+Date.now().toString(36).toUpperCase()+'-'+Math.random().toString(36).slice(2,7).toUpperCase();
let run=newRun(uid('SF')),tickets=[],online=true,currentStop=0,busy=false,failPrint=false,reach=false,trial=null,trialTick,toastTimer,attempts=[],entry='guided',rushView='compose',quick={destination:null,quantity:1},lastJourney=null,requestSeq=0,picker='guided',cashIndex=null,stopPage=0,paymentPage=0,stopListPage=0,stopSearch='';
try{const saved=JSON.parse(localStorage.getItem('safar-guided-v3')||'null');if(saved){run=restoreRun(saved.run);tickets=saved.tickets.filter(t=>validTicket(t)&&/^[A-Z0-9-]+$/.test(t.id));online=saved.online!==false;currentStop=saved.currentStop||0;attempts=(saved.attempts||[]).filter(a=>Number.isFinite(a.seconds));entry=saved.entry==='rush'?'rush':'guided';rushView=saved.rushView==='queue'?'queue':'compose';if(saved.quick&&Number.isInteger(saved.quick.destination)&&saved.quick.destination>run.origin&&saved.quick.destination<STOPS.length&&Number.isInteger(saved.quick.quantity)&&saved.quick.quantity>0&&saved.quick.quantity<100)quick=saved.quick;lastJourney=saved.lastJourney||null;requestSeq=Number.isSafeInteger(saved.requestSeq)?saved.requestSeq:0;}}catch{}
const delay=ms=>new Promise(r=>setTimeout(r,ms));
function persist(){try{localStorage.setItem('safar-guided-v3',JSON.stringify({run,tickets,online,currentStop,attempts,entry,rushView,quick,lastJourney,requestSeq}));}catch{toast('Browser storage unavailable. Keep this page open to retain records.');}}
function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,4200);}
function change(fn){if(busy)return;try{fn();render();persist();}catch(e){toast(e.message);}}
function button(label,act,extra='',cls='issue-btn'){return `<button class="${cls}" data-act="${act}" ${extra}>${label}</button>`;}
function groupTicket(g){return g.ticketId?tickets.find(t=>t.id===g.ticketId):null;}
function stepIndex(){return run.step==='destinations'?0:run.step==='passengers'?1:2;}
function paymentLabel(g){const p=g.payment;return p.status==='paid'?'✓ Paid by '+(p.method==='cash'?'cash':'UPI'):p.status==='pending'?'Waiting for UPI':p.status==='unknown'?'UPI status unknown':p.status==='failed'?'Payment failed · retry available':'Payment not collected';}
function render(){
 run.groups.forEach(g=>{if(!g.requestCode)g.requestCode='A'+String(++requestSeq).padStart(3,'0');});
 $('#guided-mode').setAttribute('aria-pressed',String(entry==='guided'));$('#rush-mode').setAttribute('aria-pressed',String(entry==='rush'));
 $('#guided-mode').disabled=busy;$('#rush-mode').disabled=busy;
 $('#wizard-progress').hidden=entry==='rush';$('#app').dataset.mobile=String(mobileView());
 $('#boarding-name').textContent=STOPS[run.origin];$('#locked-label').textContent=run.selected.length?'• FIXED FOR THIS RUN':'';$('#change-origin').disabled=busy||committed(run)||run.step==='complete';
 $('#connection').innerHTML=`<span class="status-dot"></span> ${online?'Online':'Offline · cash only'}`;$('#connection').className=online?'':'offline';
 const failure=tickets.some(t=>t.printError&&!t.printed);$('#printer-status').textContent=failure?'▤ Printer needs paper':'▤ Paper tickets only';$('#printer-status').style.color=failure?'var(--amber)':'';
 $('#wizard-progress').innerHTML=['Destinations','Passengers','Payment'].map((name,i)=>`<span class="${i===stepIndex()?'current':i<stepIndex()?'completed':''}"><b>${i<stepIndex()?'✓':i+1}</b>${name}</span>`).join('');
 if(mobileView())renderMobile();else if(entry==='rush'&&!run.editingPayment)renderRush();else if(run.step==='destinations')renderDestinations();else if(run.step==='passengers')renderCounts();else if(run.step==='payments')renderPayments();else renderComplete();
 $('#lab-network-label').textContent=online?'Online · UPI status can be simulated':'Offline · UPI disabled, cash available';$('#toggle-network').textContent=online?'Go offline':'Reconnect';
 $('#reach-overlay').hidden=!reach;$('#reach-toggle').classList.toggle('active',reach);$('#reach-toggle').setAttribute('aria-pressed',String(reach));
 [['#step-dest',run.step!=='destinations'],['#step-qty',run.step==='payments'||run.step==='complete'],['#step-issue',run.step==='complete']].forEach(([s,d])=>{$(s).classList.toggle('done',d);$(s+' b').textContent=d?'✓':'○';});
 $('#trial-results').innerHTML=attempts.length?attempts.map((a,i)=>`<div class="result-row"><span>Attempt ${attempts.length-i} · ${a.correct?'Correct task':'Different journey'}</span><strong>${a.seconds.toFixed(2)}s · full demo flow</strong></div>`).join(''):'No attempts yet. Times include all steps and simulated printing.';
 persist();
}
function tile(i){const pos=run.selected.indexOf(i);return `<button class="destination ${pos>=0?'selected':''}" data-act="select" data-index="${i}" aria-pressed="${pos>=0}"><span class="dest-name">${STOPS[i]}</span><span class="dest-fare">${money(fare(run.origin,i))} / adult</span>${pos>=0?`<span class="tile-check">${run.mode==='multi'?pos+1:'✓'}</span>`:''}</button>`;}
function renderDestinations(){
 $('#wizard-screen').innerHTML=`<div class="ticket-mode" role="group" aria-label="Selection mode"><button data-act="single" aria-pressed="${run.mode==='single'}">Single destination</button><button data-act="multi" aria-pressed="${run.mode==='multi'}">Multiple destinations</button></div><div class="wizard-title"><span class="micro-label">STEP 1 OF 3</span><h2>${run.mode==='single'?'Where are they going?':'Pick all destinations.'}</h2><p>${run.mode==='single'?'One stop. Any passenger count.':'Choose the stops first. Counts come next.'}</p></div><div class="destinations">${COMMON.filter(i=>i>run.origin).map(tile).join('')}</div><button class="all-stops" data-act="all-stops"><span>All ${STOPS.length-run.origin-1} stops</span><span>View route →</span></button><div class="selection-list"><span class="micro-label">${run.selected.length?run.selected.length+' SELECTED · IN THIS ORDER':'YOUR SELECTION'}</span>${run.selected.length?run.selected.map((d,i)=>`<button data-act="select" data-index="${d}" class="selection-chip"><span>${i+1}</span>${STOPS[d]}<b>×</b></button>`).join(''):'<p>Tap a destination to begin.</p>'}</div><div class="paper-note">▤ Every journey receives a printed ticket.</div>`;
 $('#wizard-controls').innerHTML=`${button(`<span>${run.selected.length?'Set passenger counts':'Select a destination'}</span><span>${run.selected.length?run.selected.length+' →':'→'}</span>`,'begin',run.selected.length&&!busy?'':'disabled')}<div class="collection-hint">${run.mode==='multi'?'You can choose more than one stop before continuing.':'Cash or UPI payment comes after passenger count.'}</div>`;
}
function renderCounts(){
 const g=run.groups[run.active],n=run.groups.length;
 $('#wizard-screen').innerHTML=`<button class="wizard-back" data-act="back-count">← ${run.editingPayment?'Back · discard changes':run.active?'Previous destination':'Edit destinations'}</button><div class="wizard-title"><span class="micro-label">STEP 2 OF 3 · DESTINATION ${run.active+1} OF ${n}</span><h2>How many passengers?</h2><p>${run.editingPayment?'Save confirms corrections. Back discards changes.':'Set the count for this destination only.'}</p></div><div class="count-journey"><span>FROM ${STOPS[run.origin]}</span><h3>${STOPS[g.destination]}</h3>${run.editingPayment?button('Change destination','edit-destination','','edit-destination-btn'):''}<span>${money(fare(run.origin,g.destination))} per adult</span><div class="big-count">${g.quantity}<small>${g.quantity===1?'passenger':'passengers'}</small></div></div><div class="count-progress">${run.groups.map((item,i)=>`<span class="${i===run.active?'active':item.confirmed?'done':''}"><b>${item.confirmed&&i!==run.active?'✓':i+1}</b><span>${STOPS[item.destination]}${item.confirmed?' · '+item.quantity:''}</span></span>`).join('')}</div>`;
 $('#wizard-controls').innerHTML=`<div class="count-label"><h2>Passengers to ${STOPS[g.destination]}</h2><span>Adult fare</span></div><div class="quantity">${[1,2,3,4].map(q=>`<button data-act="count" data-index="${q}" class="${q===g.quantity?'selected':''}" aria-pressed="${q===g.quantity}">${q}</button>`).join('')}<button data-act="more" class="more-quantity ${g.quantity>4?'selected':''}">${g.quantity>4?g.quantity:'More'}</button></div><div class="fare-line"><span>${g.quantity} adults × ${money(fare(run.origin,g.destination))}</span><strong>${money(amount(run,g))}</strong></div>${button(`<span>${run.editingPayment?'Save changes':run.active<n-1?'Next destination':'Continue to payments'}</span><span>→</span>`,'next-count')}<div class="collection-hint">${run.active<n-1&&!run.editingPayment?'Up next: '+STOPS[run.groups[run.active+1].destination]:'Each destination will have a separate payment.'}</div>`;
}
function paymentCard(g,i){
 const p=g.payment,locked=['pending','unknown','paid'].includes(p.status),t=groupTicket(g);
 return `<article class="payment-card ${p.status==='paid'?'is-paid':''}"><div class="payment-heading"><span class="group-number request-code">${g.requestCode||i+1}</span><div><strong>${STOPS[g.destination]}</strong><small>${g.quantity} adults × ${money(fare(run.origin,g.destination))}</small></div><strong>${money(amount(run,g))}</strong></div>${p.status==='paid'?`<div class="payment-status paid">${paymentLabel(g)}</div>${g.changeDue?'<div class="payment-status">Change to return: '+money(g.changeDue)+'</div>':''}<div class="payment-reference">Ref: ${p.reference}</div><div class="locked-copy">Paid · corrections need operator refund / reissue</div>${t?.printed?'<div class="printed-state">▤ Ticket printed <span>✓</span></div>':button(t?.printError?'Retry this slip':'Print this ticket','print-one',`data-index="${i}" ${busy?'disabled':''}`,'payment-action')}`:`<div class="payment-method" role="group" aria-label="Payment for ${STOPS[g.destination]}"><button data-act="cash-method" data-index="${i}" aria-pressed="${p.method==='cash'}" ${locked||busy?'disabled':''}>₹ Cash</button><button data-act="upi-method" data-index="${i}" aria-pressed="${p.method==='upi'}" ${locked||busy||!online?'disabled':''}>▦ UPI / online</button><button class="edit-count" data-act="edit-count" data-index="${i}" ${locked||busy?'disabled':''}>Edit</button></div>${p.method==='cash'&&!locked?button('Change calculator','cash-change',`data-index="${i}"`,'cash-calculator-link'):''}${locked?'<div class="locked-copy">Pending payment · editing locked</div>':''}${p.status!=='unpaid'?`<div class="payment-status ${p.status==='failed'?'failed':'waiting'}">${paymentLabel(g)}</div>`:''}${button(p.method==='cash'?`Cash received · ${money(amount(run,g))}`:!online?'Reconnect for UPI':['pending','unknown'].includes(p.status)?'Check this payment':'Show payment QR · '+money(amount(run,g)),p.method==='cash'?'cash-paid':'upi',`data-index="${i}" ${busy||(p.method==='upi'&&!online)?'disabled':''}`,'payment-action')}`}</article>`;
}
function renderPayments(){
 const ready=paidUnprinted(run,tickets).length,paid=run.groups.filter(g=>g.payment.status==='paid').length;
 $('#wizard-screen').innerHTML=`<button class="wizard-back" data-act="back-payments" ${committed(run)||run.expressQueue?'disabled':''}>← Review passenger counts</button><div class="wizard-title"><span class="micro-label">STEP 3 OF 3</span><h2>Payments stay separate.</h2><p>Choose Cash or UPI for each destination.</p></div><div class="payment-progress"><span>${paid} of ${run.groups.length} payments received</span><span>▤ Paper tickets</span></div>${run.groups.map(paymentCard).join('')}`;
 $('#wizard-controls').innerHTML=`${button(`<span>${busy?'Printing…':ready?'Print '+ready+' paid '+(ready===1?'ticket':'tickets'):'Collect a payment first'}</span><span>▤</span>`,'print',ready&&!busy?'':'disabled')}<div class="collection-hint">Paid journeys can print while another payment is pending.</div>`;
}
function renderComplete(){
 const list=run.groups.map(groupTicket).filter(Boolean);
 $('#wizard-screen').innerHTML=`<div class="complete-icon">✓</div><div class="wizard-title complete-title"><span class="micro-label">READY TO HAND OVER</span><h2>${list.length} ${list.length===1?'ticket':'tickets'} printed.</h2><p>Separate payments. Separate paper slips.</p></div>${run.groups.map((g,i)=>`<button class="complete-ticket" data-act="ticket" data-id="${g.ticketId}"><span class="group-number request-code">${g.requestCode||i+1}</span><div><strong>${STOPS[g.destination]}</strong><small>${g.quantity} adults · ${g.payment.method==='cash'?'Cash':'UPI'} paid · Printed</small></div><strong>${money(amount(run,g))}</strong><span>↗</span></button>`).join('')}<a class="print-format-link" href="${printURL(list)}" target="_blank" rel="noopener">Open printable slips / Save PDF ↗</a><p class="delivery-caption">Printer actions are simulated. Browser print layouts are available.</p>`;
 $('#wizard-controls').innerHTML=`${button('<span>Next passengers</span><span>→</span>','new')}<div class="collection-hint">New selection. Fresh passenger counts.</div>`;
}
function openSheet(kicker,title,html){$('#sheet-kicker').textContent=kicker;$('#sheet-title').textContent=title;$('#sheet-content').innerHTML=html;if(!$('#sheet').open)$('#sheet').showModal();$('#sheet-content').scrollTop=0;}
function closeSheet(){$('#sheet').close();}
function openDialog(name){closeSheet();$('#'+name+'-dialog').showModal();}
function closeDialogs(){$$('.wide-dialog').forEach(d=>d.close());closeSheet();}
function showStops(){picker='guided';stopListPage=0;stopSearch='';openSheet('CHOOSE DESTINATIONS',run.mode==='multi'?'Select all requested stops':'Select a stop','<input id="stop-search" class="stop-search" type="search" aria-label="Find a stop" placeholder="Find a stop (optional)"><div class="stop-list" id="stop-list"></div><button class="sheet-action" data-act="close-sheet">Done selecting</button>');stopList();$('#sheet .close-sheet').focus({preventScroll:true});}
function stopList(){
 const selected=picker==='quick'?[quick.destination]:picker==='edit'?[run.groups[run.active].destination]:run.selected;
 const matches=STOPS.map((name,i)=>({name,i})).filter(x=>x.i>run.origin&&x.name.toLowerCase().includes(stopSearch.toLowerCase())&&(picker!=='selected'||selected.includes(x.i)));
 const size=mobileView()?4:STOPS.length,pages=Math.max(1,Math.ceil(matches.length/size));stopListPage=Math.min(stopListPage,pages-1);
 $('#stop-list').innerHTML=matches.slice(stopListPage*size,(stopListPage+1)*size).map(({name,i})=>`<button class="stop-row ${selected.includes(i)?'selected':''}" data-act="${picker==='quick'?'quick-stop':picker==='edit'?'edit-stop':'sheet-stop'}" data-index="${i}" aria-pressed="${selected.includes(i)}"><span class="stop-number">${selected.includes(i)?'✓':i+1}</span><strong>${name}</strong><span>${money(fare(run.origin,i))}</span></button>`).join('')+(pages>1?mobilePager(stopListPage,pages,'stop-list-page','stops'):'')||'<p class="empty-state">No matching stops.</p>';
}
function showMore(){const q=run.groups[run.active].quantity;openSheet('PASSENGER COUNT','More passengers',`<p>Adults travelling to ${STOPS[run.groups[run.active].destination]}. Choose 1–99.</p><div class="more-grid">${[5,6,7,8,9,10].map(n=>`<button data-act="more-count" data-index="${n}">${n}</button>`).join('')}</div><label class="custom-count-label" for="custom-count">Or enter a count</label><input class="stop-search" id="custom-count" type="number" inputmode="numeric" min="1" max="99" value="${q}" aria-label="Custom passenger count"><button class="sheet-action" data-act="save-more">Use this count</button>`);}
function showUpi(i){
 const g=run.groups[i];if(!g)return;try{requestUpi(run,i,uid('UPI'),online);persist();render();}catch(e){toast(e.message);return;}
 const p=g.payment;const sample=`SAFAR DESIGN DEMO | ${p.reference} | ${STOPS[g.destination]} | INR ${p.amount} | NOT A PAYMENT REQUEST`;
 openSheet('SEPARATE UPI PAYMENT · DEMO',g.requestCode+' · '+STOPS[g.destination],`<div class="upi-amount"><span>${g.quantity} adults · ${money(fare(run.origin,g.destination))} each</span><strong>${money(p.amount)}</strong><small>Only this destination’s payment</small></div><div class="ticket-qr demo-payment-qr">${qrSVG(sample)}</div><div class="demo-qr-label">DEMO QR · CANNOT TRANSFER MONEY</div><div class="upi-status ${p.status==='unknown'?'unknown':''}">${p.status==='unknown'?'Status unknown · resolve this request':'Waiting for payment confirmation'}</div><p class="upi-reference">Request: ${p.reference}</p><button class="sheet-action secondary" data-act="check-upi" data-index="${i}">Check payment status</button><div class="simulation-box"><span class="micro-label">PROTOTYPE CONTROLS · NO MONEY MOVES</span><div><button data-act="upi-success" data-index="${i}">Simulate success</button><button data-act="upi-failure" data-index="${i}">Failure</button><button data-act="upi-unknown" data-index="${i}">Interrupted</button></div></div><button class="sheet-action secondary" data-act="upi-later">Keep pending · next passenger →</button><p class="payment-safety">Real confirmation must come from the payment service. A screenshot or scanning alone does not confirm payment. The ticket will be printed.</p>`);
}
async function upiOutcome(i,result){if(busy)return;const g=run.groups[i],reference=g?.payment.reference;if(!reference)return;busy=true;$$('.simulation-box button').forEach(b=>b.disabled=true);await delay(400);try{resolveUpi(run,i,reference,result,online);persist();render();if(result==='unknown'){busy=false;showUpi(i);}else{closeSheet();toast(result==='paid'?STOPS[g.destination]+': UPI received (demo). Ready to print.':'Payment failed. Retry UPI or choose cash.');}}catch(e){toast(e.message);}finally{busy=false;render();}}
function printURL(list){return new URL('print.html',location.href).href+'#'+list.map(encodeTicket).join('.');}
async function printReady(index=null){
 if(busy)return;let work;try{work=preparePrint(run,tickets);}catch(e){toast(e.message);return;}if(index!==null)work=work.filter(t=>t.id===run.groups[index]?.ticketId);if(!work.length)return;
 busy=true;work.forEach(t=>t.synced=online);persist();render();const breakAt=failPrint?(work.length>1?1:0):Infinity;failPrint=false;await delay(550);
 work.forEach((t,i)=>{t.printError=i>=breakAt;if(!t.printError){t.printed=true;t.copies++;}});busy=false;
 if(allPrinted(run,tickets)){run.step='complete';finishTrial();}if(entry==='rush'){rushView='queue';}persist();render();$('#app-scroll').scrollTop=0;
 if(work.some(t=>t.printError))toast('Paper ran out. Paid tickets are saved. Retry the remaining slips—do not collect payment again.');else toast(index!==null&&run.groups[index]?.changeDue?'Printed '+run.groups[index].requestCode+'. Return '+money(run.groups[index].changeDue)+' change.':work.length+' printed '+(work.length===1?'ticket':'tickets')+'. No combined payment.');
}
function showTicket(id){const t=tickets.find(x=>x.id===id);if(!t)return;openSheet('PAPER TICKET · DEMO RECORD','Ticket details',`<div class="receipt"><div class="receipt-status">${t.printed?'✓ PRINTED':'SAVED · NOT PRINTED'}</div><h3>${STOPS[t.destination]}</h3><p>From ${STOPS[t.origin]} · ${t.quantity} adults</p><div class="receipt-details"><div><span>Fare</span><strong>${money(t.unit)} × ${t.quantity}</strong></div><div><span>Payment</span><strong>${t.paymentMethod==='upi'?'UPI':'Cash'} received</strong></div><div><span>Reference</span><strong>${t.paymentReference||'Demo'}</strong></div><div><span>Copies</span><strong>${t.copies}</strong></div></div><div class="receipt-total"><span>This ticket only</span><strong>${money(t.total)}</strong></div><div class="receipt-id">${t.id}<br>SAMPLE · NOT VALID FOR TRAVEL</div></div><a class="print-format-link" href="${printURL([t])}" target="_blank" rel="noopener">Open printable slip / Save PDF ↗</a><button class="sheet-action" data-act="copy-print" data-id="${t.id}">${t.printed?'Print a copy (demo)':'Retry print (demo)'}</button><button class="sheet-action secondary" data-act="close-sheet">Back</button>`);}
async function reprint(id){if(busy)return;const t=tickets.find(x=>x.id===id);if(!t)return;busy=true;await delay(400);t.printed=true;t.printError=false;t.copies++;if(allPrinted(run,tickets)){run.step='complete';finishTrial();}busy=false;persist();render();showTicket(id);}
function history(){openSheet('SAVED ON THIS BROWSER','Recent printed tickets',tickets.length?tickets.map(t=>`<button class="history-row" data-act="ticket" data-id="${t.id}"><span><strong>${STOPS[t.destination]}</strong><small>${t.quantity} adults · ${t.paymentMethod==='upi'?'UPI':'Cash'} paid · ${t.printed?'Printed':'Awaiting print'}</small></span><span>${money(t.total)}</span></button>`).join(''):'<p class="empty-state">No issued tickets yet.</p>');}
function showOrigin(){if(committed(run)){toast('Boarding is locked once a payment starts.');return;}openSheet('CORRECT BEFORE PAYMENT','Boarding stop',`<p>Changing boarding clears the current draft. No payments have been taken.</p><div class="stop-list">${STOPS.slice(0,-1).map((n,i)=>`<button class="stop-row" data-act="origin" data-index="${i}"><span class="stop-number">${i+1}</span><strong>${n}</strong><span>${i===run.origin?'✓':''}</span></button>`).join('')}</div>`);}
function settings(){openSheet('TRIP SETUP','Route 308',`<div class="setting-row"><span>Direction</span><strong>Majestic → Whitefield</strong></div><div class="setting-row"><span>Fare category</span><strong>Adults · illustrative fares</strong></div><div class="setting-row"><span>Payment choices</span><strong>Cash or UPI per destination</strong></div><div class="setting-row"><span>Ticket delivery</span><strong>Printed only</strong></div><p style="margin-top:18px">UPI, syncing and portable printing are simulated. This version follows destinations → counts → individual payments.</p><button class="settings-action" data-open="notes">Design notes ↗</button><button class="settings-action" data-open="lab">Test scenarios ↗</button>`);}
function setMode(mode,confirmed=false){if(run.selected.length>1&&mode==='single'&&!confirmed){openSheet('SINGLE DESTINATION','Keep only the first stop?',`<p>${STOPS[run.selected[0]]} will stay selected. Other destinations will be removed from this unpaid draft.</p><button class="sheet-action" data-act="confirm-single">Keep ${STOPS[run.selected[0]]}</button><button class="sheet-action secondary" data-act="close-sheet">Keep multiple destinations</button>`);return;}run.mode=mode;if(mode==='single')run.selected=run.selected.slice(0,1);render();persist();}
function startNew(){cancelTrial();stopPage=0;paymentPage=0;currentStop=run.origin;run=newRun(uid('SF'),currentStop,run.mode);quick={destination:null,quantity:1};rushView='compose';persist();render();$('#app-scroll').scrollTop=0;}
function resetScenario(name){if(busy)return;if(committed(run)&&!allPrinted(run,tickets)){openSheet('ACTIVE PAYMENTS','Finish this run first','<p>There is a paid or pending journey. Print paid tickets and resolve pending payments before loading another scenario.</p><button class="sheet-action" data-act="close-sheet">Return to current run</button>');return;}closeDialogs();cancelTrial();stopPage=0;paymentPage=0;entry=name==='rush'?'rush':'guided';rushView=name==='rush'?'queue':'compose';quick={destination:null,quantity:1};run=newRun(uid('SF'),0,['batch','mixed','print','pending','rush'].includes(name)?'multi':'single');currentStop=0;failPrint=false;online=name!=='offline';
 if(['batch','mixed','print','pending','rush'].includes(name)){[3,6,11].forEach(d=>toggleStop(run,d));if(name!=='batch'){beginCounts(run);[3,2,4].forEach(q=>{setCount(run,q);nextCount(run);});method(run,1,'upi');}}
 if(name==='print'){for(let i=0;i<run.groups.length;i++){method(run,i,'cash');confirmCash(run,i,uid('CASH'));}failPrint=true;}
 if(name==='pending'||name==='rush'){requestUpi(run,1,uid('UPI'),true);if(name==='pending')resolveUpi(run,1,run.groups[1].payment.reference,'unknown',true);}
 persist();render();$('#phone').scrollIntoView({behavior:'auto',block:'center'});if(name==='batch')toast('Destinations selected. Next: set 3, then 2, then 4 passengers.');
}
function toggleNetwork(){online=!online;if(online)tickets.forEach(t=>t.synced=true);persist();render();toast(online?'Reconnected. UPI status checks are available in the demo.':'Offline: cash available. Pending UPI requests stay unresolved.');}
function cancelTrial(){if(trial){trial=null;clearInterval(trialTick);$('#trial-time').textContent='—';$('#trial-copy').textContent='Attempt cancelled. Start again when ready.';}}
function startTrial(){if(committed(run)&&!allPrinted(run,tickets)){toast('Finish the active payments first.');return;}resetScenario('normal');trial={start:performance.now()};$('#trial-copy').textContent='MG Road → 3 adults → cash received → print.';trialTick=setInterval(()=>{if(trial)$('#trial-time').textContent=((performance.now()-trial.start)/1000).toFixed(2)+'s';},50);}
function finishTrial(){if(!trial)return;const seconds=(performance.now()-trial.start)/1000,correct=run.groups.length===1&&run.groups[0].destination===3&&run.groups[0].quantity===3&&run.groups[0].payment.method==='cash';attempts.unshift({seconds,correct});attempts=attempts.slice(0,20);trial=null;clearInterval(trialTick);$('#trial-time').textContent=seconds.toFixed(2)+'s';$('#trial-copy').textContent=`${correct?'Correct task.':'Different journey.'} Full guided flow: ${seconds.toFixed(2)}s, including simulated printing.`;}
function action(name,b){const i=Number(b?.dataset.index);if(busy&&!['close-sheet'].includes(name))return;
 switch(name){
 case 'mobile-stop-page':stopPage=Math.max(0,i);render();break;case 'mobile-payment-page':paymentPage=Math.max(0,i);render();break;
 case 'mobile-selected':mobileSelected();break;case 'mobile-quick-options':mobileQuickOptions();break;
 case 'mobile-repeat':closeSheet();repeatJourney();break;case 'mobile-history':history();break;
 case 'mobile-settings':settings();break;case 'mobile-reach':closeSheet();reach=!reach;render();break;
 case 'stop-list-page':stopListPage=Math.max(0,i);stopList();break;
 case 'guided-mode':switchEntry('guided');break;case 'rush-mode':switchEntry('rush');break;
 case 'rush-compose':rushView='compose';render();persist();break;case 'rush-queue':rushView='queue';render();persist();break;
 case 'quick-stop':quick.destination=i;closeSheet();render();persist();break;
 case 'quick-count':quick.quantity=i;render();persist();break;
 case 'quick-more':showQuickMore();break;case 'save-quick-more':saveQuickMore();break;
 case 'quick-all':showDestinationPicker('quick');break;
 case 'quick-clear':quick={destination:null,quantity:1};render();persist();break;
 case 'quick-repeat':repeatJourney();break;
 case 'quick-add':commitQuick('queue');break;case 'quick-cash':commitQuick('cash');break;case 'quick-upi':commitQuick('upi');break;case 'quick-change':commitQuick('change');break;
 case 'edit-destination':showDestinationPicker('edit');break;case 'edit-stop':change(()=>editDestination(run,i));closeSheet();break;
 case 'upi-later':closeSheet();switchEntry('rush');rushView='compose';render();persist();toast('Request stays pending. Add the next passenger; return to Queue to check it.');break;
 case 'cash-change':showCashChange(i);break;case 'cash-note':setCashNote(i);break;case 'confirm-cash-note':confirmCashNote();break;
 case 'select':change(()=>toggleStop(run,i));break;
 case 'sheet-stop':change(()=>toggleStop(run,i));stopList();break;
 case 'single':setMode('single');break;case 'multi':setMode('multi');break;case 'confirm-single':setMode('single',true);closeSheet();break;
 case 'begin':change(()=>beginCounts(run));$('#app-scroll').scrollTop=0;break;
 case 'count':change(()=>setCount(run,i));break;case 'more':showMore();break;
 case 'more-count':change(()=>setCount(run,i));closeSheet();break;
 case 'save-more':{const q=Number($('#custom-count').value);if(!Number.isInteger(q)||q<1||q>99){toast('Enter a whole number from 1 to 99.');return;}change(()=>setCount(run,q));closeSheet();break;}
 case 'next-count':change(()=>{nextCount(run);if(entry==='rush')rushView='queue';});$('#app-scroll').scrollTop=0;break;
 case 'back-count':change(()=>{if(run.editingPayment){cancelEdit(run);rushView='queue';}else if(run.active)run.active--;else run.step='destinations';});break;
 case 'back-payments':if(!committed(run)&&!run.expressQueue)change(()=>{run.step='passengers';run.active=0;});break;
 case 'edit-count':change(()=>editCount(run,i));$('#app-scroll').scrollTop=0;break;
 case 'cash-method':change(()=>method(run,i,'cash'));break;case 'upi-method':change(()=>method(run,i,'upi'));break;
 case 'cash-paid':change(()=>confirmCash(run,i,uid('CASH')));break;
 case 'upi':showUpi(i);break;case 'upi-success':upiOutcome(i,'paid');break;case 'upi-failure':upiOutcome(i,'failed');break;case 'upi-unknown':upiOutcome(i,'unknown');break;
 case 'check-upi':toast(online?'No provider is connected. Use the clearly labelled demo controls to test an outcome.':'Reconnect to check this payment.');break;
 case 'print':printReady();break;case 'print-one':printReady(i);break;
 case 'new':startNew();break;case 'all-stops':showStops();break;case 'close-sheet':closeSheet();break;
 case 'ticket':showTicket(b.dataset.id);break;case 'copy-print':reprint(b.dataset.id);break;
 case 'origin':change(()=>{stopPage=0;paymentPage=0;currentStop=i;run=newRun(uid('SF'),i,run.mode);quick={destination:null,quantity:1};});closeSheet();break;
 }
}
// Event delegation keeps every screen interactive after a step transition.
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b||b.disabled)return;if(b.dataset.act)action(b.dataset.act,b);if(b.dataset.open)openDialog(b.dataset.open);if(b.dataset.scenario)resetScenario(b.dataset.scenario);if(b.classList.contains('close-sheet'))closeSheet();if(b.classList.contains('close-dialog'))b.closest('dialog').close();});
document.addEventListener('input',e=>{if(e.target.id==='stop-search'){stopSearch=e.target.value;stopListPage=0;stopList();}if(e.target.id==='cash-received')updateCashChange();});
$('#change-origin').addEventListener('click',showOrigin);$('#settings').addEventListener('click',()=>mobileView()?mobileMenu():settings());$('#recent-tickets').addEventListener('click',history);
$('#printer-status').addEventListener('click',()=>{const t=tickets.find(x=>x.printError&&!x.printed);if(t)showTicket(t.id);else openSheet('PRINTED DELIVERY ONLY','Portable printer ready','<p>Paper slips are the only ticket delivery format. UPI is only a payment option. This device connection is simulated.</p><button class="sheet-action" data-act="close-sheet">Back</button>');});
$('#toggle-network').addEventListener('click',()=>{if(!busy)toggleNetwork();});$('#start-trial').addEventListener('click',startTrial);$('#lab-trial').addEventListener('click',startTrial);
$('#reach-toggle').addEventListener('click',()=>{reach=!reach;render();});$('#lab-reach').addEventListener('click',()=>{closeDialogs();reach=!reach;render();});
$('#notes-to-lab').addEventListener('click',()=>{$('#notes-dialog').close();openDialog('lab');});$('#prototype-nav').addEventListener('click',()=>{closeDialogs();$('#phone').scrollIntoView({behavior:'smooth',block:'center'});});
function switchEntry(value){
 if(run.step==='passengers'){toast('Save the current count or use Back before switching modes.');return;}
 if(value==='rush'&&entry!=='rush'&&run.step==='destinations'&&run.selected.length){toast('Finish your selected destinations first, or deselect them before opening Rush.');return;}
 entry=value;if(value==='rush')rushView=run.groups.length?'queue':'compose';persist();render();$('#app-scroll').scrollTop=0;
}
function quickStops(){const pinned=COMMON.filter(i=>i>run.origin);return [...pinned,...STOPS.map((_,i)=>i).filter(i=>i>run.origin&&!pinned.includes(i))].slice(0,4);}
function renderRush(){
 const waiting=run.groups.filter(g=>['pending','unknown'].includes(g.payment.status)).length;
 const remaining=run.groups.filter(g=>!groupTicket(g)?.printed).length;
 const nav=`<div class="rush-tabs"><button data-act="rush-compose" aria-pressed="${rushView==='compose'}">New passenger</button><button data-act="rush-queue" aria-pressed="${rushView==='queue'}">Queue <b>${remaining}</b>${waiting?'<span class="waiting-dot" aria-label="Payment waiting"></span>':''}</button></div>`;
 if(rushView==='queue'){
  const active=run.groups.map((g,i)=>({g,i})).filter(({g})=>!groupTicket(g)?.printed),done=run.groups.map((g,i)=>({g,i})).filter(({g})=>groupTicket(g)?.printed),ready=paidUnprinted(run,tickets).length;
  $('#wizard-screen').innerHTML=nav+`<div class="wizard-title"><span class="micro-label">RUSH · INDEPENDENT PAYMENTS</span><h2>Keep the queue moving.</h2><p>${waiting?waiting+' payment waiting. You can serve the next passenger.':'Collect each fare. Hand over each printed ticket.'}</p></div>`+active.map(({g,i})=>paymentCard(g,i)).join('')+(!active.length?'<div class="rush-empty"><strong>'+ (done.length?'All tickets handed over?':'Ready for the first passenger.')+'</strong><p>'+ (done.length?'Add another passenger or finish this run.':'Choose a destination to create a ticket.')+'</p></div>':'')+(done.length?`<details class="printed-details"><summary>${done.length} printed tickets</summary>${done.map(({g,i})=>`<button class="complete-ticket" data-act="ticket" data-id="${g.ticketId}"><span class="request-code">${g.requestCode}</span><div><strong>${STOPS[g.destination]}</strong><small>${g.quantity} adults · ${money(amount(run,g))} · Printed</small></div><span>↗</span></button>`).join('')}<a class="print-format-link" href="${printURL(done.map(({g})=>groupTicket(g)))}" target="_blank" rel="noopener">Open printed slips / Save PDF ↗</a></details>`:'');
  $('#wizard-controls').innerHTML=button('<span>Next passenger</span><span>＋</span>','rush-compose')+(ready?button('Print '+ready+' paid '+(ready===1?'ticket':'tickets'),'print',busy?'disabled':'','rush-secondary'):allPrinted(run,tickets)?button('Finish run · clear queue','new','','rush-secondary'):'')+'<div class="collection-hint">Pending requests stay in this queue.</div>';return;
 }
 const d=quick.destination,total=d===null?0:fare(run.origin,d)*quick.quantity;
 const repeatOK=lastJourney&&Number.isInteger(lastJourney.destination)&&lastJourney.destination>run.origin&&lastJourney.destination<STOPS.length&&lastJourney.origin===run.origin&&Number.isInteger(lastJourney.quantity)&&lastJourney.quantity>0&&lastJourney.quantity<=99;
 $('#wizard-screen').innerHTML=nav+`<div class="wizard-title rush-title"><span class="micro-label">RUSH · QUICK ENTRY</span><h2>Next stop?</h2><p>${quick.quantity} ${quick.quantity===1?'passenger':'passengers'} selected. Change the count below.</p></div><div class="destinations">${quickStops().map(i=>`<button class="destination ${d===i?'selected':''}" data-act="quick-stop" data-index="${i}" aria-pressed="${d===i}"><span class="dest-name">${STOPS[i]}</span><span class="dest-fare">${money(fare(run.origin,i))} / adult</span>${d===i?'<span class="tile-check">✓</span>':''}</button>`).join('')}</div><button class="all-stops" data-act="quick-all"><span>All ${STOPS.length-run.origin-1} stops</span><span>View route →</span></button>${repeatOK?`<button class="repeat-journey" data-act="quick-repeat"><span>↺ Same journey again</span><small>${STOPS[lastJourney.destination]} · ${lastJourney.quantity} adults · new unpaid ticket</small></button>`:''}${waiting?`<button class="pending-banner" data-act="rush-queue">${waiting} UPI ${waiting===1?'request':'requests'} waiting <span>View queue →</span></button>`:''}`;
 $('#wizard-controls').innerHTML=`<div class="count-label"><h2>${d===null?'Passenger count':STOPS[d]}</h2>${d===null?'<span>Default: 1</span>':'<button class="quick-back" data-act="quick-clear">← Back / clear</button>'}</div><div class="quantity">${[1,2,3,4].map(n=>`<button data-act="quick-count" data-index="${n}" class="${quick.quantity===n?'selected':''}" aria-pressed="${quick.quantity===n}">${n}</button>`).join('')}<button data-act="quick-more" class="more-quantity ${quick.quantity>4?'selected':''}">${quick.quantity>4?quick.quantity:'More'}</button></div><div class="fare-line"><span>${d===null?'Choose a destination':quick.quantity+' adults × '+money(fare(run.origin,d))}</span><strong>${d===null?'—':money(total)}</strong></div>${button('<span>Cash received & print</span><span>'+(d===null?'→':money(total))+'</span>','quick-cash',d===null||busy?'disabled':'')}<div class="rush-actions">${button('UPI / online','quick-upi',d===null||busy||!online?'disabled':'','rush-small')}${button('Add to queue','quick-add',d===null||busy?'disabled':'','rush-small')}${button('Cash change','quick-change',d===null||busy?'disabled':'','rush-small')}</div><div class="collection-hint">${online?'Cash button confirms money received. Printing is simulated.':'Offline · cash available; UPI needs a connection.'}</div>`;
}
function showDestinationPicker(kind){picker=kind;stopListPage=0;stopSearch='';openSheet(kind==='edit'?'CORRECT UNPAID TICKET':'QUICK DESTINATION',kind==='edit'?'Change destination':'Choose a stop','<input id="stop-search" class="stop-search" type="search" aria-label="Find a stop" placeholder="Find a stop"><div class="stop-list" id="stop-list"></div><button class="sheet-action secondary" data-act="close-sheet">Back</button>');stopList();}
function showQuickMore(){openSheet('RUSH · PASSENGER COUNT','How many passengers?',`<label class="custom-count-label" for="quick-custom-count">Adult passengers · 1–99</label><input class="stop-search" id="quick-custom-count" type="number" inputmode="numeric" min="1" max="99" value="${quick.quantity}"><button class="sheet-action" data-act="save-quick-more">Use this count</button><button class="sheet-action secondary" data-act="close-sheet">Back · keep previous count</button>`);}
function saveQuickMore(){const n=Number($('#quick-custom-count').value);if(!Number.isInteger(n)||n<1||n>99){toast('Choose a whole number from 1 to 99.');return;}quick.quantity=n;closeSheet();persist();render();}
function repeatJourney(){if(!lastJourney||lastJourney.origin!==run.origin||lastJourney.destination<=run.origin)return;quick={destination:lastJourney.destination,quantity:lastJourney.quantity};persist();render();toast('Journey copied. Review count; payment starts fresh.');}
function commitQuick(next){
 if(busy||quick.destination===null)return;
 try{
  if(next==='upi'&&!online)throw new Error('Reconnect for UPI.');
  if(allPrinted(run,tickets)){run=newRun(uid('SF'),run.origin,run.mode);}
  const i=addJourney(run,quick.destination,quick.quantity),g=run.groups[i];g.requestCode='A'+String(++requestSeq).padStart(3,'0');lastJourney={...quick,origin:run.origin};quick={destination:null,quantity:1};rushView=next==='queue'?'compose':'queue';
  if(next==='cash')confirmCash(run,i,uid('CASH'));
  if(next==='upi')method(run,i,'upi');
  persist();render();
  if(next==='cash')printReady(i);else if(next==='upi')showUpi(i);else if(next==='change')showCashChange(i);else toast(g.requestCode+' added. Choose the next destination; collect payments in Queue.');
 }catch(e){toast(e.message);}
}
function showCashChange(i){
 const g=run.groups[i];if(!g||!['unpaid','failed'].includes(g.payment.status)){toast('This payment is locked.');return;}
 method(run,i,'cash');cashIndex=i;persist();render();const total=amount(run,g),notes=[50,100,200,500].filter(n=>n>total);
 openSheet(g.requestCode+' · '+STOPS[g.destination],'Cash & change',`<div class="cash-total"><span>Total fare</span><strong>${money(total)}</strong></div><label class="custom-count-label" for="cash-received">Cash received (₹)</label><input class="stop-search" type="number" inputmode="numeric" id="cash-received" min="${total}" value="${total}"><div class="cash-notes">${[total,...notes].map((n,j)=>`<button data-act="cash-note" data-index="${n}">${j===0?'Exact':money(n)}</button>`).join('')}</div><div class="cash-change-result" role="status" aria-live="polite" id="cash-change-result">Change to return: ₹0</div><button class="sheet-action" data-act="confirm-cash-note" id="confirm-cash-note">Confirm received${entry==='rush'?' & print':''}</button><button class="sheet-action secondary" data-act="close-sheet">Back · payment not collected</button>`);
}
function setCashNote(n){$('#cash-received').value=n;updateCashChange();}
function updateCashChange(){const g=run.groups[cashIndex];if(!g)return;try{const change=cashChange(amount(run,g),Number($('#cash-received').value));$('#cash-change-result').textContent='Change to return: '+money(change);$('#confirm-cash-note').disabled=false;}catch(e){$('#cash-change-result').textContent=e.message;$('#confirm-cash-note').disabled=true;}}
function confirmCashNote(){try{const g=run.groups[cashIndex],change=cashChange(amount(run,g),Number($('#cash-received').value)),i=cashIndex;confirmCash(run,i,uid('CASH'));g.cashReceived=Number($('#cash-received').value);g.changeDue=change;closeSheet();persist();render();toast('Return '+money(change)+' change.');if(entry==='rush')printReady(i);}catch(e){toast(e.message);}}

function mobileView(){return typeof globalThis.matchMedia==='function'&&globalThis.matchMedia('(max-width: 700px)').matches;}
function mobilePager(index,total,action,label=''){return `<div class="m-pager"><button data-act="${action}" data-index="${index-1}" ${index===0?'disabled':''} aria-label="Previous ${label||'page'}">← Previous</button><span>${index+1} / ${total}</span><button data-act="${action}" data-index="${index+1}" ${index>=total-1?'disabled':''} aria-label="Next ${label||'page'}">Next →</button></div>`;}
function mobileStops(){const stops=[...COMMON.filter(i=>i>run.origin),...STOPS.map((_,i)=>i).filter(i=>i>run.origin&&!COMMON.includes(i))];const pages=Math.ceil(stops.length/4);stopPage=Math.max(0,Math.min(stopPage,pages-1));return {stops:stops.slice(stopPage*4,stopPage*4+4),pages};}
function mobileTile(i,quickEntry=false){const selected=quickEntry?quick.destination===i:run.selected.includes(i);return `<button class="m-stop ${selected?'is-selected':''}" data-act="${quickEntry?'quick-stop':'select'}" data-index="${i}" aria-pressed="${selected}"><strong>${STOPS[i]}</strong><span>${money(fare(run.origin,i))} / adult ${selected?' · ✓':''}</span></button>`;}
function renderMobile(){
 const state=run.editingPayment?'count':entry==='rush'?(rushView==='compose'?'rush':'queue'):run.step==='destinations'?'stops':run.step==='passengers'?'count':run.step==='payments'?'queue':'complete';
 $('#app').dataset.screen=state;
 if(state==='stops'){
  const {stops,pages}=mobileStops();
  $('#wizard-screen').innerHTML=`<div class="m-mode" role="group" aria-label="Destination mode"><button data-act="single" aria-pressed="${run.mode==='single'}">Single stop</button><button data-act="multi" aria-pressed="${run.mode==='multi'}">Multiple stops</button></div><div class="m-title"><h2>Choose ${run.mode==='multi'?'stops':'a stop'}</h2><button data-act="mobile-selected" ${run.selected.length?'':'disabled'}>${run.selected.length} selected</button></div><div class="m-stops">${stops.map(i=>mobileTile(i)).join('')}</div>${mobilePager(stopPage,pages,'mobile-stop-page','stops')}`;
  $('#wizard-controls').innerHTML=button(`<span>Set passenger ${run.selected.length===1?'count':'counts'}</span><span>${run.selected.length||''} →</span>`,'begin',run.selected.length?'':'disabled');return;
 }
 if(state==='count'){
  const g=run.groups[run.active];
  $('#wizard-screen').innerHTML=`<div class="m-back-row"><button data-act="back-count">← ${run.editingPayment?'Cancel edit':'Back'}</button><span>${run.editingPayment?g.requestCode+' · Edit':'Stop '+(run.active+1)+' of '+run.groups.length}</span></div><div class="m-count-route"><div><span>Passengers to</span><h2>${STOPS[g.destination]}</h2><small>${money(fare(run.origin,g.destination))} / adult</small></div>${run.editingPayment?button('Change stop','edit-destination','','m-edit-stop'):''}</div><div class="m-count-heading">How many passengers?</div><div class="m-count-grid" role="group" aria-label="Passenger count">${[1,2,3,4,5].map(n=>`<button data-act="count" data-index="${n}" aria-pressed="${g.quantity===n}">${n}</button>`).join('')}<button data-act="more" aria-pressed="${g.quantity>5}">${g.quantity>5?g.quantity:'More'}</button></div><div class="m-total"><span>${g.quantity} adults × ${money(fare(run.origin,g.destination))}</span><strong>${money(amount(run,g))}</strong></div>`;
  $('#wizard-controls').innerHTML=button(`<span>${run.editingPayment?'Save changes':run.active<run.groups.length-1?'Next destination':'Continue to payments'}</span><span>→</span>`,'next-count');return;
 }
 if(state==='rush'){
  const {stops,pages}=mobileStops(),d=quick.destination,total=d===null?0:fare(run.origin,d)*quick.quantity,pending=run.groups.filter(g=>!groupTicket(g)?.printed).length;
  $('#wizard-screen').innerHTML=`<div class="m-rush-head"><h2>Choose a stop</h2><button data-act="rush-queue">Queue · ${pending}</button></div><div class="m-stops">${stops.map(i=>mobileTile(i,true)).join('')}</div>${mobilePager(stopPage,pages,'mobile-stop-page','stops')}`;
  $('#wizard-controls').innerHTML=`<div class="m-rush-summary"><span>${d===null?'Passengers':STOPS[d]}</span><button data-act="quick-clear" ${d===null?'disabled':''}>← Clear</button><button data-act="mobile-quick-options" aria-label="Repeat journey or cash change">More •••</button></div><div class="quantity">${[1,2,3,4].map(n=>`<button data-act="quick-count" data-index="${n}" class="${quick.quantity===n?'selected':''}" aria-pressed="${quick.quantity===n}">${n}</button>`).join('')}<button class="more-quantity" data-act="quick-more">${quick.quantity>4?quick.quantity:'More'}</button></div>${button('<span>Cash received & print</span><span>'+(d===null?'—':money(total))+'</span>','quick-cash',d===null?'disabled':'')}<div class="m-rush-pay"><button data-act="quick-upi" ${d===null||!online?'disabled':''}>UPI / online</button><button data-act="quick-add" ${d===null?'disabled':''}>Add to queue</button></div>`;return;
 }
 if(state==='queue'){
  const isRush=entry==='rush',indices=run.groups.map((g,i)=>i).filter(i=>!isRush||!groupTicket(run.groups[i])?.printed),ready=paidUnprinted(run,tickets).length,waiting=run.groups.filter(g=>['pending','unknown'].includes(g.payment.status)).length;
  paymentPage=Math.max(0,Math.min(paymentPage,Math.max(0,indices.length-1)));const i=indices[paymentPage];
  $('#wizard-screen').innerHTML=`<div class="m-back-row"><button data-act="${isRush?'rush-compose':'back-payments'}" ${!isRush&&(committed(run)||run.expressQueue)?'disabled':''}>← ${isRush?'New passenger':'Review counts'}</button><span>${waiting?waiting+' UPI waiting':'Separate payments'}</span></div>`+(i===undefined?'<div class="m-done"><span>✓</span><h2>Queue complete</h2><p>Your printed tickets are saved.</p><button data-act="mobile-history">View tickets</button></div>':`<div class="m-title"><h2>${run.groups[i].payment.status==='paid'?'Ready to print':'Collect payment'}</h2><span>${paymentPage+1} of ${indices.length}</span></div><div class="m-payment">${paymentCard(run.groups[i],i)}</div>${mobilePager(paymentPage,indices.length,'mobile-payment-page','ticket')}`);
  $('#wizard-controls').innerHTML=isRush?(ready?button('<span>Print '+ready+' paid tickets</span><span>▤</span>','print'):button('<span>'+(allPrinted(run,tickets)?'Finish run':'Next passenger')+'</span><span>→</span>',allPrinted(run,tickets)?'new':'rush-compose')):button('<span>'+(ready?'Print '+ready+' paid '+(ready===1?'ticket':'tickets'):'Collect a payment above')+'</span><span>▤</span>','print',ready?'':'disabled');return;
 }
 const list=run.groups.map(groupTicket).filter(Boolean);paymentPage=Math.max(0,Math.min(paymentPage,list.length-1));const t=list[paymentPage];
 $('#wizard-screen').innerHTML=`<div class="m-done"><span>✓</span><h2>${list.length} tickets printed</h2><p>Ready to hand over</p></div>${t?`<button class="complete-ticket" data-act="ticket" data-id="${t.id}"><span class="request-code">${t.requestCode}</span><div><strong>${STOPS[t.destination]}</strong><small>${t.quantity} adults · ${money(t.total)} · ${t.paymentMethod==='cash'?'Cash':'UPI'}</small></div></button>${mobilePager(paymentPage,list.length,'mobile-payment-page','ticket')}`:''}<a class="print-format-link" href="${printURL(list)}" target="_blank" rel="noopener">Printable slips / Save PDF ↗</a>`;
 $('#wizard-controls').innerHTML=button('<span>Next passengers</span><span>→</span>','new');
}
function mobileSelected(){picker='selected';stopSearch='';stopListPage=0;openSheet('CURRENT SELECTION','Review selected stops','<div id="stop-list"></div><button class="sheet-action" data-act="close-sheet">Done</button>');stopList();}
function mobileQuickOptions(){const repeatOK=lastJourney&&lastJourney.origin===run.origin;openSheet('RUSH SHORTCUTS','Journey options',`${repeatOK?button('↺ Same journey again','mobile-repeat','','sheet-action'):''}${quick.destination!==null?button('Cash change calculator','quick-change','','sheet-action secondary'):''}<button class="sheet-action secondary" data-act="close-sheet">Back</button>`);}
function mobileMenu(){openSheet('SAFAR · DEMO','Trip & tools',`<p>${online?'Online':'Offline · cash only'} · Printed tickets only</p><button class="settings-action" data-act="mobile-history">Recent tickets →</button><button class="settings-action" data-act="mobile-settings">Route & settings →</button><button class="settings-action" data-open="notes">Design notes →</button><button class="settings-action" data-open="lab">Test lab →</button><button class="settings-action" data-act="mobile-reach">Thumb reach guide →</button>`);}

if(typeof globalThis.matchMedia==='function')globalThis.matchMedia('(max-width: 700px)').addEventListener?.('change',()=>render());

render();
